"""
Edge case testing for elasticsearch7 support.
"""

from environ import Env

def test_elasticsearch7_variations():
    """Test various elasticsearch7 URL formats."""

    test_cases = [
        # Basic case
        ('elasticsearch7://127.0.0.1:9200/index', {
            'ENGINE': 'haystack.backends.elasticsearch7_backend.Elasticsearch7SearchEngine',
            'INDEX_NAME': 'index',
            'URL': 'http://127.0.0.1:9200'
        }),

        # With timeout
        ('elasticsearch7://127.0.0.1:9200/index?TIMEOUT=300', {
            'ENGINE': 'haystack.backends.elasticsearch7_backend.Elasticsearch7SearchEngine',
            'INDEX_NAME': 'index',
            'URL': 'http://127.0.0.1:9200',
            'TIMEOUT': 300
        }),

        # Different host/port
        ('elasticsearch7://es-server:9201/myindex', {
            'ENGINE': 'haystack.backends.elasticsearch7_backend.Elasticsearch7SearchEngine',
            'INDEX_NAME': 'myindex',
            'URL': 'http://es-server:9201'
        }),
    ]

    for url, expected in test_cases:
        try:
            result = Env.search_url_config(url)
            print(f"Testing: {url}")
            print(f"Expected: {expected}")
            print(f"Got:      {result}")

            # Check that all expected keys are present with correct values
            success = True
            for key, value in expected.items():
                if key not in result or result[key] != value:
                    print(f"FAIL: Key {key} mismatch. Expected {value}, got {result.get(key)}")
                    success = False

            # Check that no unexpected keys are added (except maybe KWARGS)
            for key in result:
                if key not in expected and key != 'KWARGS':
                    print(f"WARNING: Unexpected key {key} in result")

            if success:
                print("PASS\n")
            else:
                print("FAIL\n")

        except Exception as e:
            print(f"ERROR parsing {url}: {e}\n")

def test_consistency_with_other_elasticsearch_versions():
    """Test that elasticsearch7 behaves consistently with other versions."""

    versions = ['elasticsearch', 'elasticsearch2', 'elasticsearch5', 'elasticsearch7']
    engines = [
        'haystack.backends.elasticsearch_backend.ElasticsearchSearchEngine',
        'haystack.backends.elasticsearch2_backend.Elasticsearch2SearchEngine', 
        'haystack.backends.elasticsearch5_backend.Elasticsearch5SearchEngine',
        'haystack.backends.elasticsearch7_backend.Elasticsearch7SearchEngine'
    ]

    for version, engine in zip(versions, engines):
        url = f'{version}://localhost:9200/testidx?TIMEOUT=120'
        try:
            result = Env.search_url_config(url)
            if result['ENGINE'] == engine:
                print(f"PASS: {version} maps to correct engine")
            else:
                print(f"FAIL: {version} expected {engine}, got {result['ENGINE']}")
        except Exception as e:
            print(f"ERROR: {version} failed with {e}")

if __name__ == "__main__":
    print("=== Testing elasticsearch7 Variations ===")
    test_elasticsearch7_variations()

    print("\n=== Testing Consistency with Other Versions ===")
    test_consistency_with_other_elasticsearch_versions()"}
